ssize_t l2tp6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                      size_t len, int noblock, int flags, int *addr_len)
{
    struct l2tp_session *session = l2tp_sk_to_session(sk);
    struct l2tp_tunnel *tunnel = session->tunnel;
    struct l2tp_msg *l2tp_msg;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;
    struct sockaddr_in6 *sin;

    if (flags & MSG_OOB) {
        return -EOPNOTSUPP;
    }

    if (flags & MSG_ERRQUEUE) {
        return sock_recv_errqueue(sk, msg, len, addr_len);
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        if (noblock)
            return -EWOULDBLOCK;

        return -EAGAIN;
    }

    l2tp_msg = (struct l2tp_msg *)skb->data;

    sin = (struct sockaddr_in6 *)&msg->msg_name;
    sin->sin6_family = AF_INET6;
    sin->sin6_addr = tunnel->ip6_addr;
    sin->sin6_flowinfo = 0;
    sin->sin6_scope_id = 0;
    sin->sin6_port = htons(l2tp_msg->tunnel_id);
    *addr_len = sizeof(*sin);

    if (msg->msg_flags & MSG_TRUNC)
        len = skb->len;

    copied = min_t(int, len, skb->len);
    err = memcpy_to_msg(msg, skb->data, copied);
    if (err)
        goto out;

    skb_pull(skb, copied);
    if (skb->len == 0)
        kfree_skb(skb);
    else
        skb_queue_head(&sk->sk_receive_queue, skb);

    if (copied < skb->data_len)
        msg->msg_flags |= MSG_TRUNC;

    if (flags & MSG_WAITALL)
        return copied;

    return copied;

out:
    kfree_skb(skb);
    return err;
}

ssize_t l2tp6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                      size_t len, int noblock, int flags, int *addr_len)
{
    ssize_t ret;
    struct sk_buff *skb;
    struct ipv6_pinfo *np = inet6_sk(sk);
    struct sockaddr_in6 *addr = (struct sockaddr_in6 *)msg->msg_name;
    struct l2tp_session *session = sk->sk_user_data;
    struct l2tp_tunnel *tunnel = session->tunnel;
    struct l2tp_msg *l2tpmsg;

    if (flags & MSG_OOB)
        return -EOPNOTSUPP;

    if (flags & MSG_ERRQUEUE)
        return sock_recv_errqueue(iocb, sk, msg, len, noblock, flags, addr_len);

    skb = skb_recv_datagram(sk, flags, noblock, &ret);
    if (!skb)
        return ret;

    l2tpmsg = (struct l2tp_msg *)skb->data;
    if (!l2tpmsg) {
        kfree_skb(skb);
        return -EINVAL;
    }

    ret = skb->len;
    if (len < ret)
        ret = -EMSGSIZE;
    else
        ret = copy_to_iter(skb->data, ret, msg->msg_iter);

    if (addr && addr_len) {
        addr->sin6_family = AF_INET6;
        addr->sin6_addr = *(struct in6_addr *)skb->cb;
        addr->sin6_port = 0;
        *addr_len = sizeof(*addr);
    }

    if (flags & MSG_TRUNC)
        ret = skb->len;

    if (flags & MSG_CMSG_CLOEXEC)
        set_bit(FD_CLOEXEC, &iocb->ki_filp->f_flags);

    sock_recv_timestamp(msg, sk, skb);

    kfree_skb(skb);
    return ret;
}

ssize_t l2tp6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                      size_t len, int noblock, int flags, int *addr_len)
{
    struct ipv6_pinfo *np = inet6_sk(sk);
    struct l2tp_session *session = sk->sk_user_data;
    struct l2tp_tunnel *tunnel;
    struct l2tp_ip6hdr *iph;
    struct sk_buff *skb;
    ssize_t copied;
    int peeking = flags & MSG_PEEK;
    int error = 0;

    if (session == NULL)
        return -EBADFD;

    tunnel = session->tunnel;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (skb == NULL) {
        if (noblock || (flags & MSG_DONTWAIT))
            return -EAGAIN;
        while ((skb = skb_dequeue(&sk->sk_receive_queue)) == NULL) {
            if (signal_pending(current))
                return sock_intr_errno(noblock);
            __set_current_state(TASK_INTERRUPTIBLE);
            schedule();
        }
    }

    copied = skb->len;
    if (len < copied) {
        if (!(flags & MSG_TRUNC))
            copied = len;
        else
            error = -ERANGE;
    }

    if (!peeking)
        __skb_unlink(skb, &sk->sk_receive_queue);

    if (msg) {
        memcpy(msg->msg_name, &skb->cb.l2tp6_hdr->iph, sizeof(struct in6_addr));
        if (addr_len)
            *addr_len = sizeof(struct in6_addr);
        if (copied > 0)
            memcpy(msg->msg_iov, skb->data, copied);
    }

    if (flags & MSG_OOB)
        error = -EOPNOTSUPP;
    if (flags & MSG_ERRQUEUE)
        error = sock_recv_errqueue(sk, msg, len, flags);

    kfree_skb(skb);

    return copied;
}

ssize_t l2tp_ip6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                         size_t len, int noblock, int flags, int *addr_len)
{
    struct sk_buff *skb;
    struct l2tp_session *session = sk->sk_user_data;
    struct l2tp_tunnel *tunnel = session->tunnel;
    struct ipv6hdr *iph;
    int cork_seq;
    int copied;

    if (flags & MSG_OOB)
        return -EOPNOTSUPP;

    if (flags & MSG_ERRQUEUE)
        return sock_recv_errqueue(iocb, sk, msg, len, flags, addr_len);

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        if (noblock || (flags & MSG_DONTWAIT))
            return -EAGAIN;

        skb = skb_dequeue(&sk->sk_receive_queue);
    }

    if (!skb)
        return -EAGAIN;

    cork_seq = skb->skb_iif;

    iph = ipv6_hdr(skb);
    copied = skb->len;
    if (len < copied) {
        if (copied > sk->sk_rcvlowat)
            copied = sk->sk_rcvlowat;
        if (copied > len)
            copied = len;
    }

    if (memcpy_to_msg(msg, skb->data, copied))
        copied = -EFAULT;

    if (copied > 0) {
        if (iov_iter_count(&msg->msg_iter) > 0) {
            if (iov_iter_is_linear(&msg->msg_iter))
                iov_iter_advance(&msg->msg_iter, copied);
            else
                iov_iter_advance(&msg->msg_iter, copied);
        }

        if (copied < skb->len)
            sk->sk_backlog_rcving = 1;

        if (addr_len)
            *addr_len = sizeof(struct sockaddr_in6);
    }

    kfree_skb(skb);
    return copied;
}

int l2tp_ip6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                     size_t len, int noblock, int flags, int *addr_len)
{
    struct sk_buff *skb;
    int cmsg_flags = 0;
    int ret;
    int copied;

    skb = skb_recv_datagram(sk, flags, noblock, &cmsg_flags);
    if (!skb)
        return -EAGAIN;

    copied = skb->len;
    if (len < copied) {
        copied = len;
        msg->msg_flags |= MSG_TRUNC;
    }

    ret = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (ret)
        return ret;

    if (addr_len)
        *addr_len = sizeof(struct sockaddr_in6);

    return copied;
}
